-- PostgreSQL runtime schema. text JSON columns keep the stdlib app portable;
-- application validation serializes/deserializes them as JSON at boundaries.
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE IF NOT EXISTS source_file (id uuid PRIMARY KEY, filename text NOT NULL, sha256 char(64) NOT NULL, imported_at text NOT NULL, parser_version text NOT NULL, row_count integer NOT NULL DEFAULT 0, UNIQUE(filename,sha256));
CREATE TABLE IF NOT EXISTS staged_record (id uuid PRIMARY KEY, source_file_id uuid NOT NULL REFERENCES source_file(id), record_type text NOT NULL, source_row integer NOT NULL, raw_payload text NOT NULL, disposition text NOT NULL DEFAULT 'unreviewed', disposition_reason text, created_at text NOT NULL, UNIQUE(source_file_id,record_type,source_row));
CREATE TABLE IF NOT EXISTS brand (id uuid PRIMARY KEY, name text NOT NULL, aliases text NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'draft', publication_state text NOT NULL DEFAULT 'Draft', evidence_json text NOT NULL DEFAULT '[]', updated_at text NOT NULL);
CREATE TABLE IF NOT EXISTS product (id uuid PRIMARY KEY, brand_id uuid NOT NULL REFERENCES brand(id), name text NOT NULL, aliases text NOT NULL DEFAULT '[]', version text, format text, lifecycle text NOT NULL DEFAULT 'Unverified', publication_state text NOT NULL DEFAULT 'Draft', evidence_json text NOT NULL DEFAULT '[]', updated_at text NOT NULL);
CREATE TABLE IF NOT EXISTS shade (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES product(id), name text NOT NULL, aliases text NOT NULL DEFAULT '[]', code text, original_description text, depth text, undertone text, normalization_state text NOT NULL DEFAULT 'Incomplete', depth_confidence text NOT NULL DEFAULT 'Unrated', undertone_confidence text NOT NULL DEFAULT 'Unrated', availability text NOT NULL DEFAULT 'Not Verified', availability_source text, availability_checked_at text, publication_state text NOT NULL DEFAULT 'Draft', lifecycle text NOT NULL DEFAULT 'Unverified', evidence_json text NOT NULL DEFAULT '{}', updated_at text NOT NULL);
CREATE TABLE IF NOT EXISTS match_claim (id uuid PRIMARY KEY, source_shade_id uuid NOT NULL REFERENCES shade(id), target_shade_id uuid REFERENCES shade(id), source_wording text NOT NULL, closeness text, confidence text NOT NULL DEFAULT 'Unrated', caveat text, source_file text, source_page text, evidence_json text NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'Draft', checked_at text, created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS correction_report (id text PRIMARY KEY, category text NOT NULL, description text NOT NULL, contact text, status text NOT NULL DEFAULT 'Under Review', created_at text NOT NULL, retain_until text NOT NULL, admin_notes text, resolved_at text);
CREATE TABLE IF NOT EXISTS audit_event (id uuid PRIMARY KEY, entity_type text NOT NULL, entity_id text NOT NULL, action text NOT NULL, previous_json text, proposed_json text, reason text NOT NULL, actor text NOT NULL, review_mode text NOT NULL DEFAULT 'self-review', created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS admin_session (token_hash char(64) PRIMARY KEY, created_at text NOT NULL, expires_at text NOT NULL);
CREATE INDEX IF NOT EXISTS idx_shade_product ON shade(product_id);
CREATE INDEX IF NOT EXISTS idx_claim_source ON match_claim(source_shade_id,status);
CREATE INDEX IF NOT EXISTS idx_stage_type ON staged_record(record_type,disposition);
CREATE INDEX IF NOT EXISTS idx_correction_queue ON correction_report(status,created_at);
CREATE INDEX IF NOT EXISTS idx_shade_name_trgm ON shade USING gin (name gin_trgm_ops);
